public partial class MainWindow : Window {
 readonly string assets=Path.Combine(AppContext.BaseDirectory,"Assets");
 readonly EnvironmentSetup setup=new(); Inference inference=new(); readonly Languages languages;
 Language source=Languages.Automatic,target; string? input,output,result; bool ready,busy,paused,closing; CancellationTokenSource lifetime=new(),job=new();
 Window? utility;TabControl? tabs; readonly ObservableCollection<Term> terms=new();readonly ObservableCollection<Review> reviews=new();
 public MainWindow(){InitializeComponent();languages=new(assets);target=languages.All.Single(l=>l.Code=="zh-CN");Loaded+=async(_,_)=>await Prepare();Closing+=OnClosing;PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Enter&&Keyboard.Modifiers==ModifierKeys.Control){if(!busy&&ready)StartClick(this,new());e.Handled=true;}};}
 void Log(string text){Logs.AppendText($"[{DateTime.Now:HH:mm:ss}] {text}\n");if(Logs.LineCount>500)Logs.Text=string.Join('\n',Logs.Text.Split('\n').TakeLast(500));Logs.ScrollToEnd();}
 void State(){StartButton.Content=busy?"取消翻译":"开始翻译";StartButton.IsEnabled=busy||ready&&input!=null&&output!=null;PauseButton.IsEnabled=busy&&Status.Text!="正在生成输出文件…";PauseButton.Content=paused?"继续":"暂停";OptionsGrid.IsEnabled=!busy;VerifyButton.IsEnabled=!busy;}
 async Task Prepare(){ready=false;State();RetryButton.Visibility=Visibility.Collapsed;VerifyButton.IsEnabled=false;try{await inference.Initialize(setup,assets,new Progress<string>(s=>{EnvironmentLabel.Text=s;Log(s);}),lifetime.Token);ready=true;EnvironmentLabel.Text=$"Windows x64 · llama.cpp / {inference.Backend}    |    模型：已就绪";}catch(OperationCanceledException){}catch(Exception e){Log(e.Message);EnvironmentLabel.Text="环境准备失败："+e.Message;RetryButton.Visibility=Visibility.Visible;}finally{State();}}
 async void RetryClick(object s,RoutedEventArgs e){await Prepare();}
 async void VerifyClick(object s,RoutedEventArgs e){VerifyButton.IsEnabled=false;try{var valid=await EnvironmentSetup.Valid(setup.ModelPath,EnvironmentSetup.ModelHash,lifetime.Token);Log(valid?"模型校验通过。":"模型缺失或损坏，正在修复…");if(!valid){ready=false;await inference.DisposeAsync();inference=new();await Prepare();}}catch(Exception ex){Log(ex.Message);}finally{State();}}
 void InputClick(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="支持的文档|*.epub;*.pdf;*.docx;*.txt;*.md;*.markdown",Multiselect=false};if(d.ShowDialog()==true){input=d.FileName;InputPath.Text=input;InputPath.ToolTip=input;if(output==null){output=Path.GetDirectoryName(input);OutputPath.Text=output;}State();}}
 void OutputClick(object s,RoutedEventArgs e){var d=new OpenFolderDialog();if(d.ShowDialog()==true){output=d.FolderName;OutputPath.Text=output;OutputPath.ToolTip=output;State();}}
 void ChooseLanguage(Button owner,bool auto){int level=0;var panel=new StackPanel{Margin=new Thickness(8)};var popup=new Popup{PlacementTarget=owner,Placement=PlacementMode.Bottom,StaysOpen=false,AllowsTransparency=true,Child=new Border{Background=Brushes.White,BorderBrush=Brushes.LightGray,BorderThickness=new Thickness(1),Child=new ScrollViewer{Width=340,Height=420,Content=panel}}};
 void Refresh(){panel.Children.Clear();void Row(Language l){var b=new Button{Content=l.Name+((auto?source:target).Code==l.Code?" ✓":""),Background=Brushes.White,Foreground=Brushes.DarkSlateGray,HorizontalContentAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,1,0,1)};b.Click+=(_,_)=>{if(auto)source=l;else target=l;owner.Content=l.Name+" ▾";popup.IsOpen=false;};panel.Children.Add(b);}if(auto)Row(Languages.Automatic);foreach(var l in languages.Tier(level))Row(l);if(level<3){var more=new Button{Content="更多 ▾"};more.Click+=(_,_)=>{level++;Refresh();};panel.Children.Add(more);}}
 Refresh();popup.IsOpen=true;}
 void SourceClick(object s,RoutedEventArgs e)=>ChooseLanguage(SourceButton,true);void TargetClick(object s,RoutedEventArgs e)=>ChooseLanguage(TargetButton,false);
 void SwapClick(object s,RoutedEventArgs e){if(source.Code=="auto")return;(source,target)=(target,source);SourceButton.Content=source.Name+" ▾";TargetButton.Content=target.Name+" ▾";}
 async void StartClick(object s,RoutedEventArgs e){if(busy){job.Cancel();paused=false;return;}if(!ready||input==null||output==null)return;busy=true;paused=false;job.Dispose();job=new();var ct=job.Token;var src=source.Code;var dst=target.Code;bool bilingual=Bilingual.IsChecked==true,word=Format.SelectedIndex==0;Progress.Value=0;ResultButton.IsEnabled=false;Status.Text="正在解析文档与预扫描术语…";State();
 try{var doc=await Task.Run(()=>Documents.Parse(input),ct);terms.Clear();reviews.Clear();foreach(var t in Extract(doc))terms.Add(t);var translated=new List<Translation>();Status.Text="正在翻译";State();
 foreach(var segment in doc.Segments){ct.ThrowIfCancellationRequested();while(paused)await Task.Delay(150,ct);string text;try{text=segment.Kind=="code"?segment.Text:await inference.Translate(segment.Text,src,dst,languages.English,ct);}catch(Exception ex)when(ex is not OperationCanceledException){reviews.Add(new(){SegmentId=segment.Id,Reason=ex.Message,Source=segment.Text});throw;}
 foreach(var t in terms.Where(t=>t.Locked&&t.State=="已确认"&&!string.IsNullOrEmpty(t.Target)))text=text.Replace(t.Source,t.Target,StringComparison.OrdinalIgnoreCase);
 translated.Add(new(segment,text));Progress.Value=(double)translated.Count/doc.Segments.Count;Position.Text=$"{translated.Count} / {doc.Segments.Count} · {segment.Location}";}
 ct.ThrowIfCancellationRequested();Status.Text="正在生成输出文件…";State();result=await Task.Run(()=>Documents.Export(doc,translated,output,dst,bilingual,word),ct);Status.Text="翻译完成";Log("翻译完成："+result);ResultButton.IsEnabled=true;
 }catch(OperationCanceledException){Status.Text="任务已取消";Log("任务已取消。");}catch(Exception ex){Status.Text="任务失败";Log(ex.Message);}finally{busy=false;paused=false;State();}}
 static IEnumerable<Term> Extract(Document doc){var text=string.Join('\n',doc.Segments.Take(500).Select(s=>s.Text));return Regex.Matches(text,@"\b[A-Z][A-Za-z0-9]*(?:[ -][A-Z][A-Za-z0-9]*){0,3}\b").Select(m=>m.Value).Where(t=>t.Length>2&&!new[]{"The","This","That","And","For"}.Contains(t)).GroupBy(t=>t).Where(g=>g.Count()>=2).OrderByDescending(g=>g.Count()).Take(40).Select(g=>new Term{Source=g.Key,Occurrences=g.Count(),Context=doc.Segments.First(s=>s.Text.Contains(g.Key)).Text});}
 void PauseClick(object s,RoutedEventArgs e){if(!busy||!PauseButton.IsEnabled)return;paused=!paused;Status.Text=paused?"已请求暂停，当前段落完成后停止调度。":"正在翻译";State();}
 void StartMenu(object s,RoutedEventArgs e){if(!busy)StartClick(s,e);}void CancelMenu(object s,RoutedEventArgs e){if(busy){job.Cancel();paused=false;}}
 void ResultClick(object s,RoutedEventArgs e){if(result!=null)Process.Start(new ProcessStartInfo("explorer.exe",$"/select,\"{result}\""){UseShellExecute=true});}
 void ShowUtility(int index){if(utility==null){tabs=new TabControl();var grid=new DataGrid{ItemsSource=terms,AutoGenerateColumns=false,CanUserAddRows=false};grid.Columns.Add(new DataGridTextColumn{Header="术语",Binding=new System.Windows.Data.Binding("Source"),IsReadOnly=true});grid.Columns.Add(new DataGridTextColumn{Header="确认译法",Binding=new System.Windows.Data.Binding("Target")});grid.Columns.Add(new DataGridComboBoxColumn{Header="状态",ItemsSource=new[]{"待确认","已确认","已忽略"},SelectedItemBinding=new System.Windows.Data.Binding("State")});grid.Columns.Add(new DataGridCheckBoxColumn{Header="锁定",Binding=new System.Windows.Data.Binding("Locked")});grid.Columns.Add(new DataGridTextColumn{Header="次数",Binding=new System.Windows.Data.Binding("Occurrences"),IsReadOnly=true});grid.Columns.Add(new DataGridTextColumn{Header="上下文",Binding=new System.Windows.Data.Binding("Context"),IsReadOnly=true});var review=new DataGrid{ItemsSource=reviews,AutoGenerateColumns=true,CanUserAddRows=false};tabs.Items.Add(new TabItem{Header="术语建议",Content=grid});tabs.Items.Add(new TabItem{Header="检查列表",Content=review});var stack=new DockPanel{Margin=new Thickness(18)};var search=new TextBox{Margin=new Thickness(0,0,0,12),ToolTip="搜索术语或检查原因"};DockPanel.SetDock(search,Dock.Top);search.TextChanged+=(_,_)=>{System.Windows.Data.CollectionViewSource.GetDefaultView(terms).Filter=o=>o is Term t&&t.Source.Contains(search.Text,StringComparison.OrdinalIgnoreCase);System.Windows.Data.CollectionViewSource.GetDefaultView(reviews).Filter=o=>o is Review r&&r.Reason.Contains(search.Text,StringComparison.OrdinalIgnoreCase);};stack.Children.Add(search);stack.Children.Add(tabs);utility=new Window{Owner=this,Title="术语建议与检查列表",Width=700,Height=760,MinWidth=420,MinHeight=660,Content=stack};utility.Closed+=(_,_)=>utility=null;}tabs!.SelectedIndex=index;utility.Show();utility.Activate();}
 void GlossaryClick(object s,RoutedEventArgs e)=>ShowUtility(0);void ReviewClick(object s,RoutedEventArgs e)=>ShowUtility(1);
 void TextWindow(string title,string text){var w=new Window{Owner=this,Title=title,Width=760,Height=760,Content=new TextBox{Text=text,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(30),Padding=new Thickness(12)}};w.Show();}
 void SettingsClick(object s,RoutedEventArgs e){var panel=new StackPanel{Margin=new Thickness(24)};panel.Children.Add(new TextBlock{Text=EnvironmentLabel.Text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,16)});var verify=new Button{Content="重新校验模型",HorizontalAlignment=HorizontalAlignment.Left,IsEnabled=!busy};verify.Click+=VerifyClick;panel.Children.Add(verify);panel.Children.Add(new TextBlock{Text="模型目录："+setup.ModelPath,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,16,0,0)});new Window{Owner=this,Title="设置",Width=500,Height=260,Content=panel}.Show();}
 void HelpClick(object s,RoutedEventArgs e){var document=new FlowDocument{FontFamily=FontFamily,FontSize=14,PagePadding=new Thickness(42,36,42,36)};foreach(var line in File.ReadAllLines(Path.Combine(assets,"正心Translate帮助.md"))){if(string.IsNullOrWhiteSpace(line))continue;var text=line;var paragraph=new Paragraph{Margin=new Thickness(0,0,0,12),LineHeight=23};if(text.StartsWith("#")){int level=text.TakeWhile(c=>c=='#').Count();paragraph.FontSize=level==1?28:level==2?20:15;paragraph.FontWeight=FontWeights.Bold;paragraph.Margin=new Thickness(0,level==1?0:16,0,12);text=text.TrimStart('#',' ');}else if(text.StartsWith("- "))text="• "+text[2..];int cursor=0;foreach(Match match in Regex.Matches(text,@"\[([^\]]+)\]\((https://[^)]+)\)")){paragraph.Inlines.Add(new Run(text[cursor..match.Index].Replace("**","")));var link=new Hyperlink(new Run(match.Groups[1].Value)){NavigateUri=new Uri(match.Groups[2].Value)};link.RequestNavigate+=(_,a)=>{Open(a.Uri.AbsoluteUri);a.Handled=true;};paragraph.Inlines.Add(link);cursor=match.Index+match.Length;}paragraph.Inlines.Add(new Run(text[cursor..].Replace("**","")));document.Blocks.Add(paragraph);}new Window{Owner=this,Title="正心Translate 帮助",Width=760,Height=760,MinWidth=660,MinHeight=620,Content=new FlowDocumentScrollViewer{Document=document,IsToolBarVisible=false}}.Show();}
 void AboutClick(object s,RoutedEventArgs e)=>TextWindow("关于正心Translate","正心Translate Windows 开发版\n基于 TranslateGemma 4B、llama.cpp 与 BookForge\n© 北京正笔正心文化发展有限公司\nWindows 实机验收尚未完成。");
 static void Open(string url)=>Process.Start(new ProcessStartInfo(url){UseShellExecute=true});void WebsiteClick(object s,RoutedEventArgs e)=>Open("https://translate.zhengxinshushe.com");void UpdatesClick(object s,RoutedEventArgs e)=>Open("https://translate.zhengxinshushe.com/download.php");void FeedbackClick(object s,RoutedEventArgs e)=>Open("https://translate.zhengxinshushe.com/download.php#feedback");
 async void OnClosing(object? s,CancelEventArgs e){if(closing)return;e.Cancel=true;closing=true;lifetime.Cancel();job.Cancel();try{await inference.DisposeAsync();}finally{utility?.Close();Close();}}
}
public class Term {public string Source{get;set;}="";public string Target{get;set;}="";public int Occurrences{get;set;}public string Context{get;set;}="";public string State{get;set;}="待确认";public bool Locked{get;set;}}
